alter table public.agent_proposals add constraint agent_proposals_dismiss_reason_check CHECK (((dismiss_reason IS NULL) OR (dismiss_reason = ANY (ARRAY['already_handled'::text, 'not_applicable'::text, 'incorrect'::text]))));
